function plan(api) {
  // 功能表：每个区域有明确的主角、配对和最低占地。
  const brief = [
    { role: "会客与展示", count: 1, minimumFootprint: [4.2, 5.2], beside: ["协作", "工作"], zone: "living" },
    { role: "双人工位", count: 2, minimumFootprint: [4.3, 3.0], beside: ["会客与展示", "资料"], zone: "work" },
    { role: "协作餐桌", count: 1, minimumFootprint: [3.5, 3.2], beside: ["茶水", "会客与展示"], zone: "meeting" },
    { role: "茶水岛台", count: 1, minimumFootprint: [4.2, 2.0], beside: ["协作餐桌"], zone: "pantry" },
    { role: "阅读", count: 1, minimumFootprint: [3.0, 2.5], beside: ["会客与展示"], zone: "reading" },
    { role: "资料", count: 1, minimumFootprint: [3.4, 2.2], beside: ["双人工位"], zone: "library" }
  ];
  const zones = {
    living: { x: 0, z: 0.5 },
    work: { x: 4.75, z: -1.0 },
    meeting: { x: -4.8, z: -0.5 },
    pantry: { x: -1.5, z: -4.25 },
    reading: { x: -4.9, z: 3.6 },
    library: { x: 4.7, z: 4.0 }
  };
  // Reserve a continuous perimeter promenade before placing any furniture.
  // All substantial floor pieces remain inside x=±6.3, z=±4.7.
  // The perimeter connects every existing door; cross-aisles separate all zones.
  const circulation = {
    perimeterWidth: 1.0,
    crossAisles: [
      { x: -2.55, width: 0.9 },
      { x: 2.65, width: 0.9 },
      { z: 2.55, width: 0.85 }
    ],
    doors: (api.room.openings || []).filter(o => o.kind === "door")
  };
  const contract = " Coordinate contract: Y+ is up, Z+ is the front/entrance direction, X+ is right.";
  function family(key, name, dimensions, prompt, role = "functional") {
    api.requireAsset({ key, name, dimensions, prompt: prompt + contract, role });
    return key;
  }
  family("sofa", "焦糖皮沙发", [3.2, 0.83, 0.95], "One modern loft three-seat sofa, caramel saddle leather, low squared cushions, slim blackened steel base, carefully tailored seams.");
  family("coffee", "石面茶几", [1.55, 0.36, 0.72], "One low rectangular coffee table, warm ivory travertine slab top, dark smoked oak plinth base.");
  family("armchair", "阅读扶手椅", [0.9, 0.86, 0.9], "One sculptural modern lounge armchair, oatmeal boucle upholstery, exposed dark walnut frame.");
  family("side", "圆边几", [0.48, 0.54, 0.48], "One small circular side table, black steel pedestal and warm walnut top.");
  family("lamp", "落地灯", [0.44, 1.65, 0.44], "One slender black metal floor reading lamp, compact domed shade directing warm light downward, round weighted base.");
  family("rug", "编织地毯", [3.8, 0.018, 3.0], "One flat woven rectangular rug, oatmeal and charcoal fine geometric weave, clean bound edges.", "decor");
  family("desk", "橡木工作台", [1.85, 0.75, 0.82], "One modern writing desk, natural oak top, slim graphite steel legs, shallow concealed cable trough, uncluttered usable desktop.");
  family("taskchair", "办公椅", [0.64, 1.05, 0.66], "One ergonomic office chair, black mesh back, dark upholstered seat, adjustable arms, five-star caster base.");
  family("table", "协作餐桌", [2.1, 0.75, 1.0], "One rectangular collaborative dining table, solid warm oak top with softened corners, black steel trestle legs.");
  family("diningchair", "木餐椅", [0.5, 0.79, 0.53], "One modern dining chair, bent walnut backrest, charcoal upholstered seat, slender black metal legs.");
  family("island", "茶水岛台", [3.8, 0.92, 0.78], "One freestanding modern kitchenette island, matte charcoal cabinet fronts, pale stone counter, integrated small stainless sink and black faucet on the left, closed finished back, no overhead structure.");
  family("cabinet", "低矮媒体柜", [2.7, 0.55, 0.46], "One low modern media credenza, smoked oak sliding fronts, black steel feet, subtle horizontal grain.");
  family("bookcase", "开放书架", [2.8, 1.9, 0.38], "One freestanding open industrial bookcase, black steel frame, five warm oak shelves, open front and back, empty shelves ready for objects.");
  family("pendant", "线形吊灯", [1.65, 0.18, 0.18], "One minimalist linear pendant luminaire, matte black aluminum bar, warm opal underside, short integral suspension wires.", "decor");
  family("art", "抽象装饰画", [1.5, 1.25, 0.05], "One large framed abstract painting, terracotta blocks, ivory negative space and charcoal architectural strokes, slim black frame.", "decor");
  family("plant", "大型盆栽", [0.65, 1.5, 0.65], "One upright indoor rubber plant with glossy dark green leaves in a cylindrical warm gray concrete planter.", "decor");
  family("books", "设计书籍", [0.38, 0.16, 0.27], "One tidy horizontal stack of three oversized design books, cream charcoal and muted rust covers, no legible lettering.", "decor");
  family("tray", "陶杯托盘", [0.44, 0.13, 0.29], "One small walnut serving tray holding two ivory ceramic coffee cups, compact integrated tabletop still life.", "decor");
  family("screen", "桌面显示器", [0.85, 0.53, 0.19], "One thin black freestanding flat screen on a compact pedestal stand, dark display with subtle muted architectural drawing, front facing positive Z.");
  family("kettle", "咖啡机", [0.35, 0.39, 0.32], "One compact matte black espresso coffee machine, brushed steel drip tray, restrained contemporary form.", "decor");
  family("sculpture", "陶艺雕塑", [0.28, 0.4, 0.25], "One sculptural ivory ceramic vessel with an asymmetric loop silhouette, matte handmade finish.", "decor");
  family("tasklight", "桌面台灯", [0.26, 0.43, 0.26], "One compact articulated black desk lamp, circular base, small conical shade, warm downward light.", "decor");
  family("keyboard", "键盘套件", [0.6, 0.035, 0.23], "One compact wireless keyboard and mouse set on a thin charcoal desk mat, neatly aligned as a single workstation accessory.", "decor");

  function floor(key, name, x, z, rotation = 0, dimensions) {
    return api.place({
      assetId: api.asset(key), name,
      position: api.roomPoint(x, z, 0),
      rotationY: rotation,
      ...(dimensions ? { dimensions } : {})
    });
  }
  function supported(key, parentId, offset, dimensions, name) {
    return api.attach({
      assetId: api.asset(key), parentId, kind: "supported",
      offset, anchorY: "bottom",
      ...(dimensions ? { dimensions } : {}),
      ...(name ? { name } : {})
    });
  }
  function pendant(name, x, z, length) {
    return api.place({
      assetId: api.asset("pendant"), name,
      position: api.ceilingPoint(x, z, 0.18, 0.75),
      dimensions: [length, 0.18, 0.18]
    });
  }

  // Living anchor: sofa faces the presentation screen at 3.8 m.
  // Coffee table lies 0.45–0.65 m from the sofa's front edge.
  const L = zones.living;
  floor("rug", "会客区编织地毯", L.x, L.z, 0, [3.9, 0.018, 3.25]);
  const sofa = floor("sofa", "朝向展示屏的主沙发", L.x, L.z + 1.25, Math.PI);
  const coffee = floor("coffee", "沙发前茶几", L.x, L.z - 0.3);
  supported("books", coffee, [-0.43, 0.02]);
  supported("tray", coffee, [0.4, 0.02]);
  const media = floor("cabinet", "展示屏媒体柜", L.x, L.z - 2.55);
  supported("screen", media, [0, 0], [1.95, 1.12, 0.26], "会客区大屏");
  supported("sculpture", media, [-1.12, 0], [0.2, 0.3, 0.2]);
  const sofaSide = floor("side", "沙发随手边几", -1.98, L.z + 1.25);
  supported("sculpture", sofaSide, [0, 0], [0.19, 0.28, 0.18]);
  pendant("会客区线形光", L.x, L.z, 1.65);

  // Two desks form one east-side work bank. Chair fronts sit 0.15 m
  // from desktop fronts; the chairs have a clear retreat zone behind.
  const W = zones.work;
  for (const dx of [-1.02, 1.02]) {
    const desk = floor("desk", "并列橡木工位", W.x + dx, W.z);
    supported("screen", desk, [0, -0.21]);
    supported("keyboard", desk, [0, 0.22]);
    supported("tasklight", desk, [-0.69, -0.2]);
    supported("books", desk, [0.66, -0.04], [0.27, 0.1, 0.21]);
    floor("taskchair", "面向桌面的办公椅", W.x + dx, W.z + 0.89, Math.PI);
  }
  pendant("双人工位照明", W.x, W.z, 2.9);
  floor("plant", "工位侧绿植", 6.05, -2.75);

  // Meeting anchor: four chairs face the table with 0.12 m edge gaps.
  const M = zones.meeting;
  floor("rug", "协作区地毯", M.x, M.z, 0, [3.1, 0.018, 2.8]);
  const table = floor("table", "四人协作餐桌", M.x, M.z);
  for (const dx of [-0.62, 0.62]) {
    floor("diningchair", "协作桌北侧座椅", M.x + dx, M.z - 0.885);
    floor("diningchair", "协作桌南侧座椅", M.x + dx, M.z + 0.885, Math.PI);
  }
  supported("tray", table, [0.52, 0]);
  supported("books", table, [-0.55, 0]);
  supported("sculpture", table, [0, 0], [0.18, 0.26, 0.17]);
  pendant("协作餐桌吊灯", M.x, M.z, 1.65);

  // Pantry is an island, not a false wall: 1.36 m rear promenade.
  const P = zones.pantry;
  const island = floor("island", "开放茶水岛台", P.x, P.z);
  supported("kettle", island, [1.33, -0.04]);
  supported("tray", island, [0.52, 0.04]);
  pendant("茶水岛台工作光", P.x, P.z, 2.5);
  floor("plant", "茶水区端景绿植", -4.65, -4.05);

  // Reading constellation: chair + lamp + arm's-reach table + books + rug.
  const R = zones.reading;
  floor("rug", "阅读角地毯", R.x, R.z, 0, [2.5, 0.018, 1.85]);
  floor("armchair", "面向室内的阅读椅", R.x, R.z, Math.PI - 0.25);
  const readingTable = floor("side", "阅读椅边几", R.x - 0.85, R.z - 0.05);
  supported("books", readingTable, [0, 0], [0.31, 0.13, 0.23]);
  floor("lamp", "阅读椅后落地灯", R.x + 0.72, R.z + 0.23);

  // Library shelves face into the studio; books attach to shelf heights.
  const B = zones.library;
  const shelves = floor("bookcase", "南侧开放资料架", B.x, B.z + 0.28, Math.PI);
  const shelfHeights = [0.13, 0.49, 0.85, 1.21, 1.57];
  for (let row = 0; row < shelfHeights.length; row++) {
    for (const column of [-0.93, 0, 0.93]) {
      api.attach({
        assetId: api.asset((row + Math.round(column * 10)) % 3 === 0 ? "sculpture" : "books"),
        parentId: shelves, kind: "supported", anchorY: "bottom",
        offset: [column, shelfHeights[row], 0],
        dimensions: (row + Math.round(column * 10)) % 3 === 0
          ? [0.2, 0.28, 0.2] : [0.45, 0.18, 0.25],
        role: "decor"
      });
    }
  }
  floor("plant", "资料区绿植", 6.1, 3.35);

  // Long wall spans receive art only where openings leave a safe interval.
  function wallArt(wall, offset, width, height, bottom) {
    const overlaps = (api.room.openings || []).some(o => {
      if (o.wall !== wall) return false;
      const center = Number.isFinite(o.offset) ? o.offset : 0;
      const openingWidth = Number.isFinite(o.width) ? o.width : 1.6;
      return Math.abs(center - offset) < (openingWidth + width) / 2 + 0.3;
    });
    if (overlaps) return;
    const frame = api.wallFrame(wall, offset, bottom, 0.04);
    api.place({
      assetId: api.asset("art"), name: "LOFT抽象艺术挂画",
      position: frame.point, facing: { direction: frame.inward },
      dimensions: [width, height, 0.05], role: "decor"
    });
  }
  wallArt("north", -1.5, 2.2, 1.35, 1.75);
  wallArt("west", 0, 1.7, 1.35, 1.65);
  wallArt("east", -0.8, 2.0, 1.25, 1.8);
  wallArt("south", -4.9, 1.5, 1.25, 1.8);
  // Guarantee the art family is represented even if every wall span is glazed.
  api.attach({
    assetId: api.asset("art"), parentId: shelves,
    kind: "mounted", side: "north", offset: [0, 1.17],
    dimensions: [0.66, 0.53, 0.04], role: "decor",
    name: "资料架小幅艺术画"
  });
}

const brief = [
  { role: "睡眠", count: 1, minimumFootprint: [6.4, 4.7], beside: ["床边照明", "床尾休憩"], zone: "北侧睡眠区" },
  { role: "床边照明", count: 2, minimumFootprint: [0.8, 0.7], beside: ["睡眠"], zone: "北侧睡眠区" },
  { role: "床尾休憩", count: 1, minimumFootprint: [1.8, 0.55], beside: ["睡眠"], zone: "北侧睡眠区" },
  { role: "阅读", count: 1, minimumFootprint: [2.6, 3.0], beside: ["茶几", "阅读灯"], zone: "西侧阅读区" },
  { role: "梳妆", count: 1, minimumFootprint: [2.3, 2.7], beside: ["坐凳", "镜子"], zone: "东侧梳妆区" },
  { role: "衣物收纳", count: 1, minimumFootprint: [3.0, 1.8], beside: ["中央通道"], zone: "南侧更衣区" },
  { role: "展示收纳", count: 1, minimumFootprint: [2.1, 1.6], beside: ["中央通道"], zone: "南侧展示区" }
];
const zones = {
  sleep: { bounds: [-3.3, 3.3, -5.85, -1.05] },
  reading: { bounds: [-6.8, -3.5, -1.1, 3.15] },
  vanity: { bounds: [3.5, 6.8, -1.1, 3.15] },
  dressing: { bounds: [-6.8, -1.5, 3.6, 5.85] },
  display: { bounds: [1.5, 6.8, 3.6, 5.85] },
  circulation: { bounds: [-3.4, 3.4, -1.0, 5.85], minimumWidth: 1.0 }
};

// Door approach rectangles are reserved before choosing furniture anchors.
const reservations = [];
const openings = Array.isArray(api.room.openings) ? api.room.openings : Object.values(api.room.openings || {});
for (const o of openings) {
  if (o.kind !== "door" && o.type !== "door") continue;
  const offset = Number.isFinite(o.offset) ? o.offset : 0;
  const half = (Number.isFinite(o.width) ? o.width : 1.2) / 2 + 0.45;
  if (o.wall === "north") reservations.push([offset - half, offset + half, -6, -3.65]);
  if (o.wall === "south") reservations.push([offset - half, offset + half, 3.65, 6]);
  if (o.wall === "west") reservations.push([-7, -4.65, offset - half, offset + half]);
  if (o.wall === "east") reservations.push([4.65, 7, offset - half, offset + half]);
}
const intersects = (a, b) => a[0] < b[1] && a[1] > b[0] && a[2] < b[3] && a[3] > b[2];
const free = box => !reservations.some(r => intersects(box, r));
const assets = {};
const contract = " Coordinate contract: Y+ is up, Z+ is the front/entrance direction, X+ is right.";
function family(key, name, dimensions, prompt, role = "functional") {
  assets[key] = { dimensions, role };
  api.requireAsset({ key, name, dimensions, role, prompt: prompt + contract });
}
family("bed", "奶油软包双人床", [2.85, 1.38, 2.65], "One luxurious king bed, tall softly curved oatmeal upholstered headboard at the back, low smoked oak plinth, ivory linen duvet, layered terracotta and sand pillows, folded warm camel wool blanket at the foot, elegant complete bedding, no surrounding furniture.");
family("nightstand", "橡木床头柜", [0.72, 0.56, 0.58], "One warm natural oak bedside cabinet with a rounded rectangular top, two drawers and small aged brass pulls.");
family("lamp", "陶瓷床头灯", [0.36, 0.55, 0.36], "One glowing warm bedside lamp, softly textured ivory ceramic base and pleated flax fabric shade.", "decor");
family("bedrug", "羊毛卧室地毯", [5.7, 0.025, 4.15], "One flat rectangular handwoven ivory wool rug with subtle taupe border and quiet warm beige texture.", "decor");
family("bench", "床尾长凳", [1.85, 0.46, 0.55], "One low upholstered bedroom bench with camel boucle cushion, rounded corners and four walnut legs.");
family("chair", "阅读扶手椅", [1.04, 0.96, 1.02], "One generous sculptural reading armchair in warm ivory boucle with walnut feet, a single burnt sienna cushion and a folded soft knitted throw.");
family("sidetable", "圆形阅读边几", [0.58, 0.54, 0.58], "One small round walnut pedestal side table with a solid round usable tabletop.");
family("floorlamp", "黄铜阅读落地灯", [0.46, 1.63, 0.46], "One slender antique brass reading floor lamp with weighted circular base and a warm cream linen shade.");
family("books", "床边书册", [0.29, 0.105, 0.21], "One tidy stack of three clothbound books in cream, cinnamon and muted olive, no readable lettering.", "decor");
family("readrug", "阅读圆毯", [2.65, 0.022, 2.65], "One round flat woven wool reading rug in warm muted caramel with fine concentric texture.", "decor");
family("vanity", "橡木梳妆台", [1.8, 0.77, 0.55], "One refined natural oak vanity desk with two shallow drawers, open knee space, rounded corners and slim tapered legs.");
family("stool", "梳妆圆凳", [0.57, 0.47, 0.57], "One round upholstered vanity stool with ivory boucle seat and short walnut legs.");
family("mirror", "拱形梳妆镜", [1.02, 1.25, 0.07], "One wall-mounted arch-top mirror with thin aged brass frame and softly reflective glass.", "decor");
family("wardrobe", "橡木衣柜", [2.7, 2.65, 0.67], "One freestanding warm oak wardrobe with four closed doors, finely fluted inset panels, subtle brass vertical handles and recessed plinth. Finished sides, no extra objects.");
family("dresser", "卧室斗柜", [1.95, 0.88, 0.52], "One low warm walnut bedroom dresser with six drawers, rounded edges, fine brass pulls and a clear flat top.");
family("art", "暖色抽象画", [1.52, 0.92, 0.055], "One framed quiet abstract landscape painting in ivory, clay, dusty rose and warm taupe, tactile paper surface, thin oak frame, no text.", "decor");
family("pendant", "亚麻吊灯", [1.05, 0.66, 1.05], "One soft sculptural linen pendant light with rounded layered ivory shade, warm glowing diffuser and a short brass suspension stem.", "decor");
family("tray", "梳妆托盘", [0.4, 0.15, 0.25], "One travertine vanity tray holding two small amber perfume bottles and one closed ivory jewelry box, composed as one tabletop object.", "decor");
family("vase", "花枝陶瓶", [0.36, 0.64, 0.32], "One matte warm white ceramic vase holding a few airy olive branches, restrained graceful silhouette.", "decor");
family("plant", "室内橄榄树", [0.82, 1.65, 0.82], "One slender indoor olive tree with airy muted green foliage in a rounded sand-colored ceramic floor planter.", "decor");
family("cup", "茶杯碟", [0.19, 0.13, 0.19], "One handmade ivory ceramic tea cup on matching saucer, no other objects.", "decor");

function place(key, x, z, angle = 0, name) {
  return api.place({
    assetId: api.asset(key), name,
    position: api.roomPoint(x, z, 0), rotationY: angle,
    dimensions: assets[key].dimensions, role: assets[key].role
  });
}
function support(key, parentId, x = 0, z = 0) {
  return api.attach({
    assetId: api.asset(key), parentId, kind: "supported",
    offset: [x, z], anchorY: "bottom",
    dimensions: assets[key].dimensions, role: assets[key].role
  });
}
function wall(key, side, offset, bottom, inset = 0.035) {
  const f = api.wallFrame(side, offset, bottom, inset);
  return api.place({
    assetId: api.asset(key), position: f.point,
    facing: { direction: f.inward },
    dimensions: assets[key].dimensions, role: assets[key].role
  });
}
function choose(candidates, boxFor) {
  return candidates.find(v => free(boxFor(v))) ?? candidates[0];
}

// The bed/headboard is the dominant anchor. Its satellites share exact offsets.
// Bedside reach: 0.20–0.36 m; foot clearance: 0.45–0.65 m.
const bx = choose([0, -0.65, 0.65], x => [x - 2.55, x + 2.55, -5.8, -2.5]);
const bedZ = -4.38;
place("bedrug", bx, -3.48);
const bed = place("bed", bx, bedZ, 0, "主卧视觉中心");
for (const direction of [-1, 1]) {
  const night = place("nightstand", bx + direction * 2.03, bedZ - 0.64);
  support("lamp", night, direction * 0.12, -0.04);
  support("books", night, -direction * 0.15, 0.12);
}
place("bench", bx, bedZ + 2.11);
wall("art", "north", bx, 2.03);

// Reading focal pair: inward-facing chair and light, table at 0.65–0.80 m.
const rz = choose([0.55, 1.85, -0.65], z => [-6.65, -3.8, z - 1.4, z + 1.35]);
const rx = -5.25;
place("readrug", rx + 0.12, rz);
place("chair", rx, rz, Math.PI / 2);
const tea = place("sidetable", rx + 0.25, rz + 0.9);
support("books", tea, -0.075, -0.06);
support("cup", tea, 0.12, 0.13);
place("floorlamp", rx - 0.72, rz - 0.65);
wall("art", "west", rz, 1.55);

// Vanity/mirror pair sits against the east wall; seat is 0.8 m in front.
const vz = choose([0.45, 1.85, -0.7], z => [4.25, 6.85, z - 1.05, z + 1.05]);
const vanity = place("vanity", 6.48, vz, -Math.PI / 2);
place("stool", 5.37, vz, Math.PI / 2);
wall("mirror", "east", vz, 1.0, 0.055);
support("tray", vanity, 0.5, 0.015);
support("vase", vanity, -0.6, -0.02);

// Closed storage keeps the dressing zone calm; a full metre in front is unoccupied.
const wx = choose([-4.7, -3.45], x => [x - 1.5, x + 1.5, 4.15, 5.9]);
place("wardrobe", wx, 5.48, Math.PI);
const dx = choose([4.55, 3.1], x => [x - 1.12, x + 1.12, 4.15, 5.9]);
const dresser = place("dresser", dx, 5.52, Math.PI);
support("vase", dresser, -0.63, 0);
support("books", dresser, 0.54, 0);
support("tray", dresser, 0, 0.01);
wall("art", "south", dx, 1.35);

const plantSpot = [
  [6.1, -3.75], [-6.1, -3.75], [6.0, 3.35], [-6.0, 3.35]
].find(p => free([p[0] - 0.45, p[0] + 0.45, p[1] - 0.45, p[1] + 0.45])) || [3.5, -4.5];
place("plant", plantSpot[0], plantSpot[1]);

api.place({
  assetId: api.asset("pendant"),
  name: "中央柔光亚麻吊灯",
  position: api.ceilingPoint(0, -0.05, 0.66, 0.18),
  dimensions: assets.pendant.dimensions,
  role: "decor"
});

