}

function floor(key, name, x, z, angle = 0) {
  return api.place({
    assetId: api.asset(key), name,
    position: api.roomPoint(x, z, 0),
    rotationY: angle,
    dimensions: dimensions[key],
    role: definitions.find(d => d[0] === key)[4]
  });
}
function supported(key, name, parentId, x, z) {
  return api.attach({
    assetId: api.asset(key), name, parentId,
    kind: "supported", offset: [x, z],
    anchorY: "bottom", dimensions: dimensions[key],
    role: definitions.find(d => d[0] === key)[4]
  });
}
function hanging(key, name, x, z, drop) {
  return api.place({
    assetId: api.asset(key), name,
    position: api.ceilingPoint(x, z, dimensions[key][1], drop),
    dimensions: dimensions[key], role: "decor"
  });
}

