    id: "corner-cafe-entrance", kind: "door", wall: "south",
    offset: 0, bottom: 0, width: 1.2, height: 2.6
  });
  door = { id, kind: "door", wall: "south", offset: 0, bottom: 0, width: 1.2, height: 2.6 };
  actualOpenings.push(door);
}
api.place({
  assetId: api.asset("door"), roomOpeningId: door.id,
  dimensions: [door.width || 1.2, door.height || 2.6, 0.12],
  role: "functional"
});

let windows = existing.filter(o => o.kind === "window");
if (!windows.length) {
  const proposals = [
    { wall: "south", offset: -4.8, width: 3.0 },
    { wall: "south", offset: 4.8, width: 3.0 },
    { wall: "west", offset: 2.8, width: 2.7 }
  ];
  for (let i = 0; i < proposals.length; i++) {
    const p = proposals[i];
    const blocked = actualOpenings.some(o =>
      o.wall === p.wall &&
      Math.abs((o.offset || 0) - p.offset) < ((o.width || 1.2) + p.width) / 2 + 0.25
    );
    if (blocked) continue;
    const id = api.opening({
      id: "corner-cafe-glazing-" + i, kind: "window",
      wall: p.wall, offset: p.offset, bottom: 0.35,
      width: p.width, height: 2.6
    });
    const w = { id, kind: "window", wall: p.wall, offset: p.offset, bottom: 0.35, width: p.width, height: 2.6 };
    windows.push(w);
    actualOpenings.push(w);
  }
}
