  api.place({
    assetId: api.asset("window"), roomOpeningId: w.id,
    dimensions: [w.width || 3, w.height || 2.6, 0.12],
    role: "functional"
  });
}

// Wall layers choose clear wall intervals, never covering a door or window.
const wallClaims = [];
function wallPiece(key, name, choices, bottom) {
  const size = dimensions[key];
  for (const [wall, offset] of choices) {
    const halfLength = wall === "north" || wall === "south" ? 8 : 6;
    if (Math.abs(offset) + size[0] / 2 > halfLength - 0.25) continue;
    const collides = actualOpenings.some(o =>
      o.wall === wall &&
      Math.abs((o.offset || 0) - offset) < ((o.width || 1.2) + size[0]) / 2 + 0.18 &&
      bottom < (o.bottom || 0) + (o.height || 2.6) + 0.1 &&
      bottom + size[1] > (o.bottom || 0)
    ) || wallClaims.some(o =>
      o.wall === wall &&
      Math.abs(o.offset - offset) < (o.width + size[0]) / 2 + 0.12 &&
      bottom < o.bottom + o.height + 0.12 &&
      bottom + size[1] > o.bottom - 0.12
    );
    if (collides) continue;
    const frame = api.wallFrame(wall, offset, bottom, size[2] / 2 + 0.025);
    wallClaims.push({ wall, offset, bottom, width: size[0], height: size[1] });
    return api.place({
      assetId: api.asset(key), name, position: frame.point,
      facing: { direction: frame.inward }, dimensions: size, role: "decor"
    });
  }
  // A high clerestory position remains above standard door and window heads.
  for (const wall of ["north", "east", "west", "south"]) {
    for (const offset of [-4, 0, 4]) {
      const f = api.wallFrame(wall, offset, 3.05, size[2] / 2 + 0.025);
      const scaled = [size[0], Math.min(size[1], 0.65), size[2]];
      if (wallClaims.some(o => o.wall === wall && Math.abs(o.offset - offset) < (o.width + size[0]) / 2 && o.bottom + o.height > 3)) continue;
      wallClaims.push({ wall, offset, bottom: 3.05, width: scaled[0], height: scaled[1] });
      return api.place({
        assetId: api.asset(key), name, position: f.point,
        facing: { direction: f.inward }, dimensions: scaled, role: "decor"
      });
    }
  }
}

