      dimensions: dims[key], role: "decor"
    });
    return true;
  }

  // Reception anchor: guest side faces the cross-promenade; a 0.91m
  // working aisle separates the desk from its rear storage.
  const r = zones.reception.hero;
  const desk = floor("desk", r[0], r[1], 0, "主接待台");
  const cred = floor("cred", r[0], r[1] - 1.65, 0, "前台后柜");
  floor("workchair", r[0] - 1.15, r[1] - 0.96, 0, "接待工作位");
