  top("books", cred, -1.7, 0);
  top("vase", cred, 1.7, 0);
  floor("plant", -10.15, -5.8);
  hanging(r[0] - 1.4, r[1], "接待左吊灯");
  hanging(r[0] + 1.4, r[1], "接待右吊灯");

  // Dominant lobby relationship: the window-backed sofa faces a paired
  // conversation group, with its oval tea table at seating distance.
  const l = zones.lounge.hero;
  floor("rug", l[0], 4.05, 0, "休憩区地毯");
  const sofa = floor("sofa", l[0], l[1], Math.PI, "南窗会客长沙发");
