  floor("floorlamp", l[0] - 3.05, l[1] - 0.1);
  top("books", leftSide, 0, 0);
  top("vase", rightSide, 0, 0);
  top("tea", coffee, -0.5, 0);
  top("books", coffee, 0.58, 0);
  hanging(l[0], l[1] - 1.8, "会客织物吊灯");

  // Water bar: rear display, clear bartender aisle, counter, then stools.
  const b = zones.bar.hero;
  const bar = floor("bar", b[0], b[1], 0, "绿釉水吧");
  floor("backbar", b[0], -6.35, 0, "酒杯陈列后柜");
  for (const dx of [-1.8, -0.6, 0.6, 1.8]) {
    floor("stool", b[0] + dx, b[1] + 1.18, Math.PI, "水吧客座");
  }
