  hanging(b[0] - 1.5, b[1], "水吧左吊灯");
  hanging(b[0] + 1.5, b[1], "水吧右吊灯");
  floor("plant", 10.15, -5.75);

  // Four two-person dining constellations; chairs sit on the east/west
  // edges, leaving continuous north/south service aisles between tables.
  for (const x of [4.1, 8.6]) {
    for (const z of [2.65, 5.55]) {
      const table = floor("diningtable", x, z, 0, "全日餐厅双人桌");
