  top("water", service, -0.33, 0);
  top("books", service, 0.4, 0);

  // Wall layers never obstruct known openings. Try different clear spans
  // so both art families remain represented even with unusual door layouts.
  let artPlaced = false;
  let reliefPlaced = false;
  for (const candidate of [
    ["north", -7, 1.75], ["west", -3.8, 1.8],
    ["east", 3.8, 1.8], ["north", 7, 2.45]
  ]) {
    if (!artPlaced) artPlaced = wallArt("art", candidate[0], candidate[1], candidate[2]);
    else if (!reliefPlaced) reliefPlaced = wallArt("relief", candidate[0], candidate[1], candidate[2]);
  }
  if (!artPlaced) {
    const frame = api.wallFrame("west", 0, 2.5, 0.07);
    api.place({ assetId: api.asset("art"), position: frame.point, facing: { direction: frame.inward }, dimensions: [2.2, 0.8, 0.055], role: "decor" });
  }
  if (!reliefPlaced) {
    const frame = api.wallFrame("east", 0, 3.3, 0.07);
    api.place({ assetId: api.asset("relief"), position: frame.point, facing: { direction: frame.inward }, dimensions: [2.6, 0.45, 0.09], role: "decor" });
  }
}

